insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('70a9bde6-01ce-4b79-a9e2-97efa1252a1d', 'ja', '断られることは、たいてい何を映していますか？', '["相手がどれだけ心地よく感じているか", "こちらの伝え方のミス", "魅力の低さ", "人付き合いの失敗"]'::jsonb, '身を引く行動のほとんどは、評価ではなく、自分を守るためのものです。')
