insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4792cc41-039e-460b-9a94-6f1fdb50ceb7', 'ja', '断られたあと、本物の自信はどこにありますか？', '["求められなかったときにも、自分を保っていられること", "断られることをすべて避けること", "誰からも認められること", "相手に引かれるたびに、それを正そうとすること"]'::jsonb, '自信とは、周りの反応に関係なく、落ち着いたままでいられることです。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('db69db01-07df-42b3-8e90-41a34457e803', 'ja', '短い会話のあと、彼女が礼儀正しく断ってその場を離れます。どう考えるべきですか？', '["何かまずいことを言って、失敗した", "自分の価値が判定され、足りないと見なされた", "彼女は、自分の心地よさやタイミングを守っていた", "追いかけて、挽回する必要がある"]'::jsonb, '断るという行為は、たいてい自分を守るためのものであって、こちらへの判決ではありません。')
