insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('43e16323-ce86-4e7f-9c28-27d04a6dcc33', 'ja', '過去の経験に対して、どんな力を持っていますか？', '["完全に消し去る力", "今後の気まずさを、すべて防ぐ力", "周りの人に、無理やり忘れさせる力", "これから先に持っていく意味と物語を、選ぶ力"]'::jsonb, 'どう見るかを決めるのは、物語の書き手である自分です。書き換えることで、ネガティブなノイズから自由になれます。')
