insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b74e3d6f-b4f5-4f7f-a9fe-edc477912533', 'ja', 'ある男性が、自信が持てるまで声をかけるのを待っています。何が問題ですか？', '["自信は証拠から生まれるので、待つとそれが遅れる", "まず、内面の信念の持ち方に取り組むべきだ", "行動する前に、もっと心の準備が必要だ"]'::jsonb, '心は、行動から得た測れる証拠を信頼します。先に来るのは、自信ではなく勇気です。')
