insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('12f0ca40-33ce-4e67-bffb-cfc678a28f97', 'ja', 'ある男性が、ためらいながらも声をかけます。脳は何を記録していますか？', '["「それでもやった」が、自分にはできるという証拠になる", "「恐れを乗り越えた」が、時間とともに心の回復力を育てる", "「勇気があった」が、前向きな自己イメージを強める", "上のすべて"]'::jsonb, 'どれも本人にとっての効果で、次も声をかける可能性を高めます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b0b79ba6-0f99-427a-8b41-59a2b41ccda1', 'ja', '人付き合いのスキルの上達を、最も強く左右するものは何ですか？', '["繰り返し練習を続ける粘り強さ", "生まれつきの才能と、もともとの社交性", "受けた指導やアドバイスの質"]'::jsonb, '上達は、時間をかけて積み重ねた練習から生まれます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('d3e5a977-5717-4d10-aebd-1477b55d9977', 'ja', '二人の男性が、ぎこちないやり取りを経験します。一人はもう一度挑戦し、一人はやめます。何が違うのですか？', '["一人は練習が足りないと結論づけ、もう一人は能力がないと結論づけた", "一人には生まれつきの社交性があり、もう一人にはなかった", "一人には、土台となるより良いテクニックと基礎があった"]'::jsonb, '違いは、やり取りそのものではなく、そこから引き出した結論にあります。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
