insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('28ccfdfd-13b7-4bf5-9d16-e2ade47fa571', 'ja', '浅い呼吸は、体に何を伝えますか？', '["安全", "脅威", "集中", "自信"]'::jsonb, '速い呼吸は、体に危険を伝えます。呼吸をゆっくりにして、自分を落ち着かせましょう。')
