insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e40cadb9-6906-42bf-b334-b269e634ab6e', 'ja', '声をかける前に、どうすればエネルギーを高められますか？', '["少し体を動かし、ほほえみ、前向きな言葉を自分にかける", "状況を、もっと長く分析する", "自信が湧いてくるまで待つ", "緊張を避けるために、その場から引く"]'::jsonb, '体を動かすと、すぐに状態が切り替わり、エネルギーが高まります。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('d028ed4f-fd88-4a7c-8aab-17f7a78c6a9a', 'ja', 'ポジティブなエネルギーは、声をかけるときにどう影響しますか？', '["無意識のレベルで、人を引き寄せる", "やり取りを、自然に招き入れる", "完璧な見た目が必要になる"]'::jsonb, '良いエネルギーがあると、人は身を乗り出し、そばにいて気分が良くなります。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('55639c7a-b396-4a1c-ae26-431442cfe270', 'ja', '本物の笑顔は、まず何を伝えますか？', '["惹かれている気持ち", "自信", "安全と温かさ", "遊び心"]'::jsonb, '笑顔は、一瞬で「安全だ」と読み取られます。言葉を交わす前から、助けになります。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('cfa95ebd-1b35-41c8-8a50-fbcb06fee6aa', 'ja', 'ほほえむと、なぜ人とのあいだの緊張が下がるのですか？', '["注意をそらすから", "前向きな感情の反応を引き起こすから", "緊張を隠すから"]'::jsonb, 'ほほえむと、言葉を交わす前に、二人の脳がどちらも前向きさを感じ取ります。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('2886592f-4bba-4b7d-bcfc-6547f1eb778e', 'ja', '本物の笑顔は、どうやって二人ともに前向きな反応を生むのですか？', '["神経系に、脅威を伝える", "神経の働きとして、気分を良くし、ストレスを減らす", "脳が、無意識のうちに前向きな感情を映し取る"]'::jsonb, '笑顔は、会話が始まる前に、お互いの前向きな気持ちを引き出します。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('2c9f06f7-4cf4-45f9-80cd-7c8fcac8c28c', 'ja', '承認に頼ることは、なぜ自信を損なうのですか？', '["プレッシャーを生むから", "表現を制限するから", "自己不信を伝えるから", "境界線を弱めるから"]'::jsonb, '承認を必要とすることは、自分で自分を認められていないことを伝えます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('7bd56cd8-1f4f-4678-8dce-d3e92a3e8932', 'ja', '彼女が、自分とは違う意見を話します。彼女の承認を求めずにいられるのは、どれですか？', '["和を保つために、すぐに同意する", "申し訳なさそうにせず、違う見方を丁寧に伝える", "彼女に合わせて、自分の意見を変える", "衝突を避けるために、黙っている"]'::jsonb, '自分の軸を落ち着いて保つことは、必死さを見せずに、自分で自分を認めていることを伝えます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3fe6a5a2-4f72-4f9a-9d46-3a48ef587e96', 'ja', '承認を求めることは、なぜ惹かれる気持ちを遠ざけるのですか？', '["認められたいという必死さを伝えるから", "自分の価値を、彼女に受け入れられるかどうかに結びつけるから", "本心ではない振る舞いを生むから", "いつでも、より深いつながりを保証するから"]'::jsonb, '承認を求めることは、自己不信を伝えます。自分を受け入れていることは、強さを伝えます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e562de05-8b81-429d-b188-fbe14cf83db2', 'ja', 'ある男性が、何か月も練習したあとも、まだ緊張します。何を物差しにするべきですか？', '["同じくらいの練習時間で、ほかの人のほうが速く上達しているかどうか", "以前はできなかったことが、今はできるかどうか", "今の自分のスキルが、もともと自信のある男性と比べてどうか"]'::jsonb, '意味のある物差しは、以前の自分より良くなっているかどうか、だけです。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('586652d7-39f3-41aa-9a2f-cb693ae30050', 'ja', '他人と比べることは、なぜスキルを伸ばすうえで害になるのですか？', '["相手の出発点も、場数も、事情のすべても知らないから", "確実に失敗する、非現実的な期待を生むから", "内側の体験を外から見える結果と比べることになり、公平ではないから"]'::jsonb, '見えているのは相手の結果だけで、その出発点や事情は知りません。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9250aace-fa4f-4d66-95e4-793349439200', 'ja', '声をかけることを軽く感じさせてくれるものは、何ですか？', '["結果に、自分が何者かを決めさせないこと", "断られることを、プロセスのふつうの一部として受け入れること", "上の両方"]'::jsonb, '結果が自分の価値を決めなければ、声をかけることは、それほど怖くなくなります。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('53bacb30-3d41-4c17-a18d-8c00b9bc1398', 'ja', '人とのやり取りにおける「結果に左右されない」とは、どういうことですか？', '["相手の反応に関係なく、気持ちの安定を保つこと", "結果をまったく気にしないこと", "毎回、良い結果を無理やり引き出すこと", "安全でいるために、やり取りを避けること"]'::jsonb, '相手の反応に関係なく気分が安定していれば、主導権は自分に戻ってきます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('83794883-664e-42e0-89fa-abc8d0f95334', 'ja', '「結果に左右されない」とは、実際にはどういう意味ですか？', '["やり取りの結果や成功を、まったく気にしないこと", "やり取りがどうなっても、気持ちの安定を保つこと", "自分の価値や気分が、特定の結果に結びついていないこと"]'::jsonb, '結果は今でも気になります。でも、それがどう感じ、どう行動するかを決めることは、もうありません。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('39d1a173-8185-476b-ba48-a86f79e52a48', 'ja', '好意的な反応をうまく受け止める鍵は、何ですか？', '["彼女の注意を引きつけておこうと、もっとがんばること", "プレッシャーを避けるために、エネルギーを下げること", "失わないように、その場をコントロールすること", "その関心を生んだ、同じ自分のままでいること"]'::jsonb, '惹かれる気持ちを生んだその自分で、もう十分です。上乗せしたり、演じたりしてはいけません。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3b61bcf4-54dc-4de9-8ba8-813071e2e979', 'ja', '雰囲気は最高で、彼女が身を寄せてきます。頭が「次はどうする」と管理し始めます。どうするべきですか？', '["コントロールしようとせず、今この瞬間にいることへ戻る", "計画を立てるために、思考に任せる", "この機を逃すまいと、すぐに距離を縮める", "良い雰囲気から、身を引く"]'::jsonb, '物事がうまくいっているとき、するべきことは、リズムを保つことです。結果を管理することではありません。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('0b5dc6ef-1cda-498e-932d-4939839666ad', 'ja', '好意的な反応は、なぜ人を不安定にすることがあるのですか？', '["欠乏の思考から、承認を求める行動を引き起こすから", "良い気分を失う恐れを呼び起こすから", "行動を何も調整しなくてよくなるから", "機を逃すまい、コントロールしようというプレッシャーを生むことがあるから"]'::jsonb, '好意的なサインは、「失うもの」を生みます。結果を守ろうとする状態に、切り替わらないようにしましょう。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('5956bc0c-e67e-486c-9121-0d4f3f555035', 'ja', '体を鍛えることは、周りが体の変化に気づく前に、まず何を変えますか？', '["トレーニングの知識と、自分を律する力", "自分自身の見え方と、内側の自信", "注目を集める力", "会話のスキルと愛嬌"]'::jsonb, '自信は、まず自分に対する内側の見方が良くなったときに育ちます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9ec8b2af-94c5-4b1c-a704-f2bd3e950b20', 'ja', '体を鍛えることは、どうやって自信を高めるのに役立ちますか？', '["自分を大切に扱っていることの、身体的な証拠になる", "女性から見て、目に見えて魅力的になる", "恋愛にも活かせる、自分を律する力が身につく", "人の集まる場での立ち位置が上がる"]'::jsonb, '体を鍛えると、まず自分自身の見え方が変わり、それが声をかける可能性を高めます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('d0c9fead-d08c-463e-82b3-6acbc68aa42b', 'ja', '体が鍛えられていることから来る自信の変化は、何によって生まれますか？', '["自分の体は、前より動けると信じること", "鏡の中に、自分で敬意を持てる体を見ること", "人のいる場面での自己監視が減ること", "周りから褒められること"]'::jsonb, '自分への敬意は、外からの承認が関わるずっと前に、行動を形づくります。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('941578b4-3efd-48fd-bb43-567d6cc34570', 'ja', '身だしなみが整っていないと、第一印象にどう影響しますか？', '["女性は、より多くの努力を期待するようになる", "立ち位置の低さを伝える", "惹かれる気持ちが生まれる前に、最初のためらいを生む"]'::jsonb, '最初に目に入る手がかりが、会話が始まる前に、安心感と関心を左右します。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('320c1b55-513d-40ef-8b8a-5575836c5e6c', 'ja', '身だしなみを整え続けることの、内面への主な効果は何ですか？', '["褒められることで、外から認められること", "意志の力で、無理に自信をつくり出すこと", "顔や体つきが、劇的に変わること", "がんばらなくても、冴えていて整っていると感じられること"]'::jsonb, '身だしなみは自分自身の見え方を変え、それが声をかける可能性を高めます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c8f3b672-a516-497b-889c-0bb6535c7859', 'ja', '身だしなみを整えることの利点には、どんなものがありますか？', '["第一印象が良くなる", "内面の壁が減り、自然に振る舞える", "相手に、自分を大切にしていることが伝わる", "身だしなみに気を使わない男性より、有利になる"]'::jsonb, 'より整った第一印象、より自由な振る舞い、そして目に見える自分への敬意です。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
